data: {"level":1,"reviewed":{"level":1,"label":"concept","text":"Cross-entropy is the negative log-likelihood of a categorical model: average, over examples, the negative log of\nthe probability assigned to the true class. The gradient with respect to the logits has a famously simple form:\nthe predicted probabilities minus the target."},"hints_note":null}

